export function findFinancialInstrumentsById(id: string): FinancialInstrumentRecord | undefined {
  return FINANCIAL_INSTRUMENTS_DATABASE.find(item => item.id === id);
}

export function getAllFinancialInstrumentsRecords(): FinancialInstrumentRecord[] {
  return FINANCIAL_INSTRUMENTS_DATABASE;
}

export function filterFinancialInstrumentsByPredicate(predicate: (item: FinancialInstrumentRecord) => boolean): FinancialInstrumentRecord[] {
  return FINANCIAL_INSTRUMENTS_DATABASE.filter(predicate);
}

export function countFinancialInstrumentsRecords(): number {
  return FINANCIAL_INSTRUMENTS_DATABASE.length;
}
